import io
from datetime import datetime, timezone
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle

NAVY = colors.HexColor("#0B111E")
BLUE = colors.HexColor("#0284C7")
GOLD = colors.HexColor("#B7791F")

DISCLAIMER = (
    "SIMULATION ONLY. This document was generated by the VaultBridge Escrow demonstration environment. "
    "All parties, wallet addresses, transaction hashes, block numbers, balances, fees, compliance outcomes and "
    "valuations are fictional demonstration data. No real assets, payments, blockchain transactions, custody, "
    "AML/KYC approvals or compliance certifications are represented. This is not a genuine financial, regulatory "
    "or third-party certification and must not be relied upon for any purpose."
)


def _decorate(canvas, doc):
    canvas.saveState()
    w, h = A4
    canvas.setFont("Helvetica-Bold", 96)
    canvas.setFillColor(colors.Color(0.85, 0.15, 0.15, alpha=0.13))
    canvas.translate(w / 2, h / 2)
    canvas.rotate(40)
    canvas.drawCentredString(0, 0, "SIMULATION")
    canvas.restoreState()
    canvas.saveState()
    canvas.setFillColor(NAVY)
    canvas.rect(0, h - 22 * mm, w, 22 * mm, fill=1, stroke=0)
    canvas.setFillColor(colors.white)
    canvas.setFont("Helvetica-Bold", 13)
    canvas.drawString(18 * mm, h - 12 * mm, "VAULTBRIDGE ESCROW")
    canvas.setFont("Helvetica", 8)
    canvas.drawString(18 * mm, h - 17 * mm, "DEMONSTRATION REPORT — SIMULATION ENVIRONMENT")
    canvas.setFillColor(GOLD)
    canvas.drawRightString(w - 18 * mm, h - 12 * mm, "SIMULATED — NOT A REAL RECORD")
    canvas.setFillColor(colors.HexColor("#B91C1C"))
    canvas.setFont("Helvetica-Bold", 7.5)
    canvas.drawCentredString(w / 2, 10 * mm, "SIMULATION — NO REAL ASSETS OR PAYMENTS — NOT A GENUINE FINANCIAL OR REGULATORY CERTIFICATION")
    canvas.setFillColor(colors.grey)
    canvas.setFont("Helvetica", 7)
    canvas.drawRightString(w - 18 * mm, 5 * mm, f"Page {doc.page}")
    canvas.restoreState()


def build_report(title: str, reference: str, sections: list) -> bytes:
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, topMargin=32 * mm, bottomMargin=20 * mm,
                            leftMargin=18 * mm, rightMargin=18 * mm, title=f"{title} (SIMULATION)")
    ss = getSampleStyleSheet()
    h1 = ParagraphStyle("h1", parent=ss["Heading1"], textColor=NAVY, fontSize=17, spaceAfter=4)
    h2 = ParagraphStyle("h2", parent=ss["Heading3"], textColor=BLUE, fontSize=11, spaceBefore=10, spaceAfter=4)
    small = ParagraphStyle("small", parent=ss["Normal"], fontSize=8, leading=11, textColor=colors.HexColor("#334155"))
    cell = ParagraphStyle("cell", parent=ss["Normal"], fontSize=8.5, leading=11)
    stamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    story = [
        Paragraph(f"{title} — SIMULATION", h1),
        Paragraph(f"Transaction reference: <b>{reference} (SIMULATED)</b> &nbsp;|&nbsp; Generated: {stamp}", small),
        Spacer(1, 4),
        Paragraph(DISCLAIMER, small),
    ]
    for heading, rows in sections:
        story.append(Paragraph(heading, h2))
        data = [[Paragraph(f"<b>{k}</b>", cell), Paragraph(str(v), cell)] for k, v in rows]
        t = Table(data, colWidths=[60 * mm, 114 * mm])
        t.setStyle(TableStyle([
            ("GRID", (0, 0), (-1, -1), 0.4, colors.HexColor("#CBD5E1")),
            ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#F1F5F9")),
            ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ]))
        story.append(t)
    story += [Spacer(1, 12), Paragraph(DISCLAIMER, small)]
    doc.build(story, onFirstPage=_decorate, onLaterPages=_decorate)
    return buf.getvalue()
